import{_ as t,o,c as a,ah as r}from"./chunks/framework.DDXs_i7t.js";const d=JSON.parse('{"title":"Part 2: The Legacy of Aryanization","description":"","frontmatter":{},"headers":[],"relativePath":"en/drehbuch/teil-2-das-erbe-der-arisierung.md","filePath":"en/drehbuch/teil-2-das-erbe-der-arisierung.md"}'),n={name:"en/drehbuch/teil-2-das-erbe-der-arisierung.md"};function s(i,e,h,l,c,u){return o(),a("div",null,[...e[0]||(e[0]=[r('<h1 id="part-2-the-legacy-of-aryanization" tabindex="-1">Part 2: The Legacy of Aryanization <a class="header-anchor" href="#part-2-the-legacy-of-aryanization" aria-label="Permalink to &quot;Part 2: The Legacy of Aryanization&quot;">​</a></h1><p><strong>Working Title:</strong> <em>The Hour of the Bargain Hunter</em></p><p><strong>Cast:</strong> August Diehl (The Young Helmut Horten), Oliver Masucci (Hermann Strauß, Ernst and Curt Lauter - multi-role/mask play), Birgit Minichmayr (The Voice of History/Heidi Horten in flashbacks).</p><hr><h2 id="scene-1-duisburg-1933-–-the-silent-tremor" tabindex="-1">Scene 1: Duisburg 1933 – The Silent Tremor <a class="header-anchor" href="#scene-1-duisburg-1933-–-the-silent-tremor" aria-label="Permalink to &quot;Scene 1: Duisburg 1933 – The Silent Tremor&quot;">​</a></h2><p><strong>Location:</strong> In front of the main entrance of the Alsberg department store. <strong>Time:</strong> A grey Tuesday morning.</p><p>The young Helmut (August Diehl) stands on the opposite side of the street. He wears an impeccable coat. He observes the customers hesitantly entering the Jewish department store. An SA man stands in front of the door with a sign &quot;Do not buy from Jews!&quot;.</p><p><strong>HELMUT</strong> (to himself, almost clinical) The building is solid. The location is prime. Only the name... the name is in the way. It no longer fits the times.</p><p>He notes something in his notebook. His hand does not shake. He is not an ideologue; he is an optimizer.</p><hr><h2 id="scene-2-young-helmut-and-the-thank-you" tabindex="-1">Scene 2: Young Helmut and the &quot;Thank You&quot; <a class="header-anchor" href="#scene-2-young-helmut-and-the-thank-you" aria-label="Permalink to &quot;Scene 2: Young Helmut and the &quot;Thank You&quot;&quot;">​</a></h2><p><strong>Location:</strong> A smoky back room of a café. <strong>Time:</strong> Later that evening.</p><p>Helmut meets with a deputy Gauleiter. The room smells of cheap tobacco and the intoxication of power.</p><p><strong>GAULEITER</strong> Horten, you are young. You are ambitious. We need someone to take over the... &quot;market consolidation.&quot; Someone who has no sentimental attachments.</p><p><strong>HELMUT</strong> (with a cool smile) I only have attachments to the balance sheet, Herr Gauleiter. As for the Elsbergs... Alsbergs... I offer them a fair price. A very fair price... under the circumstances.</p><p><strong>GAULEITER</strong> The circumstances, Horten. Exactly. The circumstances make the price. Not the value.</p><hr><h2 id="scene-3-the-choreographed-dance-through-empty-aisles" tabindex="-1">Scene 3: The Choreographed Dance Through Empty Aisles <a class="header-anchor" href="#scene-3-the-choreographed-dance-through-empty-aisles" aria-label="Permalink to &quot;Scene 3: The Choreographed Dance Through Empty Aisles&quot;">​</a></h2><p><strong>Location:</strong> Inside the Alsberg department store. <strong>Time:</strong> After business hours.</p><p>Helmut walks through the aisles. The camera follows him in a long, fluid movement. August Diehl plays Helmut as someone who &quot;occupies&quot; the spaces before he even owns them. He touches the fabrics, tests the cash registers.</p><p><strong>HELMUT</strong> (whispering to the empty clothing racks) Soon you will be free. Free from the shadows of the past. I will dress you anew. In uniforms? No. In dreams. German dreams.</p><p>He begins a lonely waltz in the haberdashery department. It is a bizarre, almost eerie scene. A man dancing with a building he is currently stealing.</p><hr><h2 id="scene-4-the-protocol-of-the-takeover" tabindex="-1">Scene 4: The Protocol of the &quot;Takeover&quot; <a class="header-anchor" href="#scene-4-the-protocol-of-the-takeover" aria-label="Permalink to &quot;Scene 4: The Protocol of the &quot;Takeover&quot;&quot;">​</a></h2><p><strong>Location:</strong> A stuffy office in the Duisburg city hall. <strong>Time:</strong> April 23, 1936.</p><p>Helmut sits opposite the owners Hermann Strauß, Ernst and Curt Lauter (Oliver Masucci in multiple roles). The sales contract lies on the table. The air is heavy with bureaucracy and the raw fear of the sellers.</p><p><strong>ALFRED / STRAUSS</strong> (with a trembling voice) Herr Horten, 672,963 Reichsmarks? That barely covers our warehouse inventory. What about the goodwill? What about the name Alsberg, which my father built up over decades?</p><p><strong>HELMUT</strong> (coldly, matter-of-factly) The name Alsberg is an obstacle today, gentlemen. I offer you liberation from this obstacle. As of May 1st, this house will operate under my name. That is the commercial reality of 1936.</p><p><strong>CURT LAUTER</strong> It is a forced sale under the guise of legality, Herr Horten.</p><p><strong>HELMUT</strong> (leans forward, flips through the contract) It is a signature that clears your path abroad. Consider the 672,000 Reichsmarks as... a ticket to freedom. Sign here.</p><hr><h2 id="scene-5-the-aryanization-gala-1936" tabindex="-1">Scene 5: The &quot;Aryanization Gala&quot; 1936 <a class="header-anchor" href="#scene-5-the-aryanization-gala-1936" aria-label="Permalink to &quot;Scene 5: The &quot;Aryanization Gala&quot; 1936&quot;">​</a></h2><p><strong>Location:</strong> A magnificent ballroom. <strong>Time:</strong> The evening after the signing, May 1936.</p><p>August Diehl shines in a scene where Helmut is celebrated as the &quot;savior of Duisburg retail.&quot; He wears a tuxedo. Champagne corks pop. In the background hangs the draft for the first newspaper advertisement.</p><p><strong>CHRONICLER (Minichmayr, Off-voice)</strong> They celebrated not just a purchase. They celebrated the &quot;market consolidation.&quot; Helmut Horten stood in the middle and had the first advertisements printed: &quot;As of today in Aryan possession.&quot; He knew: a fortune founded on the injustice of others shines brightest when polished with the pride of the nation.</p><hr><h2 id="scene-6-the-silence-of-the-contracts" tabindex="-1">Scene 6: The Silence of the Contracts <a class="header-anchor" href="#scene-6-the-silence-of-the-contracts" aria-label="Permalink to &quot;Scene 6: The Silence of the Contracts&quot;">​</a></h2><p><strong>Location:</strong> The archive of the department store. <strong>Time:</strong> 1939.</p><p>Helmut has the old company documents of the Alsbergs destroyed. A giant paper shredder (an early version of the Reisswolf mentality) eats through the paper.</p><p><strong>HELMUT</strong> (observing the process) Paper burns well. But it&#39;s better to shred it. Then nothing remains. Not even ash that could be examined.</p><p>He takes one last photo of Siegfried Alsberg and slides it into the slot. August Diehl&#39;s face remains completely emotionless.</p><hr><h2 id="scene-7-market-consolidation-as-an-art-form" tabindex="-1">Scene 7: &quot;Market Consolidation&quot; as an Art Form <a class="header-anchor" href="#scene-7-market-consolidation-as-an-art-form" aria-label="Permalink to &quot;Scene 7: &quot;Market Consolidation&quot; as an Art Form&quot;">​</a></h2><p><strong>Location:</strong> A modernly designed shop window. <strong>Time:</strong> 1940.</p><p>Helmut personally arranges the mannequins. He removes everything that could recall the &quot;Jewish aesthetic.&quot; He places a swastika flag discreetly but unmistakably in the background.</p><p><strong>HELMUT</strong> It&#39;s about perspective. The customer doesn&#39;t want to know who was here before. They want to know what they get today. A bargain is a bargain. No matter what you call it.</p><p>He takes a step back and contemplates his work. The light from the street lamps is reflected in his glasses.</p><hr><h2 id="scene-8-the-shadow-of-war" tabindex="-1">Scene 8: The Shadow of War <a class="header-anchor" href="#scene-8-the-shadow-of-war" aria-label="Permalink to &quot;Scene 8: The Shadow of War&quot;">​</a></h2><p><strong>Location:</strong> A bunker during an air raid. <strong>Time:</strong> 1943.</p><p>Helmut sits calmly, while the earth shakes. He studies balance sheets by candlelight.</p><p><strong>HELMUT</strong> When everything is destroyed, the need will be greatest. He who has the goods will be the king of the ruins. I just have to wait. Time is on my side.</p><p>He extinguishes the candle with his fingers. The pain seems not to touch him.</p><p><strong>FADE OUT.</strong></p>',54)])])}const m=t(n,[["render",s]]);export{d as __pageData,m as default};
